// Atlas 2.5.0 — password-protected shared record editor.
(()=>{
const section=document.createElement('section');section.id='admin';section.className='admin-section';section.innerHTML=`<details class="admin-disclosure"><summary>Admin</summary><div class="admin-content"><p>Manage project records and their map locations.</p><button id="admin-open" type="button">Edit atlas</button><form id="admin-login" hidden><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">Unlock editor</button></form><p id="admin-message" role="status" aria-live="polite"></p><div id="admin-editor" hidden><div class="admin-lookup-row"><form id="project-number-form" class="admin-number-lookup"><label for="admin-project-number">Atlas project number</label><div><input id="admin-project-number" type="number" min="1" step="1" inputmode="numeric" placeholder="e.g. 12" required aria-describedby="project-number-help"><button type="submit">Open project</button></div><p id="project-number-help">Enter the number shown beside a project in this Atlas.</p><p id="project-number-status" role="status" aria-live="polite"></p></form><div class="admin-name-lookup"><label for="admin-project-search">Search projects</label><input id="admin-project-search" type="search" placeholder="Project name, country or keyword…" aria-controls="admin-search-results" autocomplete="off"><p id="admin-search-status" role="status" aria-live="polite"></p><div id="admin-search-results" class="admin-search-results" hidden></div></div></div><div class="admin-toolbar"><label>Project<select id="admin-record"><option value="">New project</option></select></label><button type="button" id="admin-new">New entry</button><button type="button" id="admin-logout">Lock editor</button></div><form id="record-form" aria-describedby="required-fields-note"><p id="required-fields-note">Fields marked with an asterisk (*) are required.</p><div id="admin-fields" class="admin-fields"></div><fieldset><legend>Country or countries *</legend><p>Choose all countries where this project operates. Map markers are created automatically.</p><input type="search" id="country-filter" placeholder="Find a country" aria-label="Filter countries"><div id="admin-countries" class="admin-countries"></div></fieldset><label class="check-label"><input type="checkbox" name="related"> Related initiative (AI not documented)</label><div class="admin-actions"><button type="submit">Save entry</button><button type="button" id="admin-delete" hidden>Delete entry</button></div></form><section class="edit-log"><h3>Edit log</h3><p>Latest 200 changes · timestamps shown in your local time</p><button id="audit-refresh" type="button">Refresh log</button><div id="audit-entries"></div></section></div></div></details>`;
document.querySelector('footer').before(section);
const $=selector=>section.querySelector(selector),form=$('#record-form'),message=$('#admin-message');
let catalog=null,current=null,busy=false,numberedIds=[];
const fields=[['name','Project name',true],['status','Evidence status',true],['kind','Category',true],['geo','Location description',true],['metric','Headline outcome',true],['metricLabel','Headline outcome explanation',true],['short','Short description',true],['outcome','Reported outcomes',true],['partners','Sponsors and partners',true],['phone','Contact phone'],['tel','Telephone link number'],['email','Contact email'],['contact','Contact notes'],['source','Primary evidence URL',true],['sourceLabel','Primary evidence link label'],['source2','Additional evidence URL'],['source2Label','Additional evidence link label'],['contactSource','Contact source URL'],['date','Evidence date / review note',true]];
const long=new Set(['short','outcome','partners','contact']);
for(const [name,title,required] of fields){const label=document.createElement('label');label.textContent=title+(required?' *':'');let input;if(name==='kind'){input=document.createElement('select');for(const [value,text] of [['','Implementation / published study'],['deployed','Implementation'],['related','Related initiative'],['pilot','Pilot / preliminary study'],['historical','Historical / related initiative']]){const option=document.createElement('option');option.value=value;option.textContent=text;input.append(option);}}else{input=document.createElement(long.has(name)?'textarea':'input');if(input.tagName==='TEXTAREA')input.rows=4;else input.type=['source','source2','contactSource'].includes(name)?'url':name==='email'?'email':'text';input.maxLength=12000;}input.name=name;input.required=!!required;label.append(input);$('#admin-fields').append(label);}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
function tell(text){message.textContent=text;}
async function refresh(){catalog=await api('/api/catalog');numberedIds=(window.atlasCatalog?.programs||catalog.programs).map(p=>p.id);const select=$('#admin-record');select.replaceChildren(new Option('New project',''));for(const p of catalog.programs)select.add(new Option('Project '+String(numberedIds.indexOf(p.id)+1).padStart(2,'0')+' · '+p.name,p.id));const countries=$('#admin-countries');countries.replaceChildren();for(const country of catalog.countries){const label=document.createElement('label');label.className='check-label';const input=document.createElement('input');input.type='checkbox';input.name='countries';input.value=country.name;label.append(input,document.createTextNode(country.name));countries.append(label);}}
function fitOutcomes(){const input=form.elements.outcome;input.style.height='auto';input.style.height=Math.max(100,input.scrollHeight+2)+'px';}
form.elements.outcome.addEventListener('input',fitOutcomes);
new ResizeObserver(()=>{if(!$('#admin-editor').hidden)fitOutcomes();}).observe(form.elements.outcome.parentElement);
function load(record){const number=record?numberedIds.indexOf(record.id)+1:0;$('#admin-project-number').value=number||'';$('#project-number-status').textContent=record?'Editing Project '+String(number).padStart(2,'0')+' · '+record.name:'';current=record;form.reset();$('#country-filter').value='';$('#admin-countries').querySelectorAll('label').forEach(l=>l.hidden=false);for(const [name]of fields)form.elements[name].value=record?.[name]?? (name==='kind'?'':'');form.elements.related.checked=!!record?.related;form.querySelectorAll('[name=countries]').forEach(c=>c.checked=!!record?.countries.includes(c.value));$('#admin-delete').hidden=!record;$('#admin-record').value=record?.id||'';requestAnimationFrame(fitOutcomes);}
function canonical(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
async function unlock(){await refresh();$('#admin-editor').hidden=false;$('#admin-login').hidden=true;$('#admin-open').hidden=true;load(null);await loadAudit();tell('Editor unlocked. Changes are saved for all visitors.');}
async function loadAudit(){const data=await api('/api/audit');const container=$('#audit-entries');container.replaceChildren();if(!data.entries.length){container.textContent='No edits have been logged yet.';return;}const table=document.createElement('table');const header=document.createElement('tr');for(const title of ['Timestamp','Version','Action','Project','IP address','Restore']){const th=document.createElement('th');th.textContent=title;header.append(th);}table.append(header);for(const row of data.entries){const tr=document.createElement('tr');for(const value of [new Date(row.at).toLocaleString(),'v'+row.revision,row.action,row.name,row.ip]){const td=document.createElement('td');td.textContent=value;tr.append(td);}const actions=document.createElement('td');for(const side of ['before','after']){const button=document.createElement('button');button.type='button';button.textContent=side==='before'?'Restore before':'Restore this version';button.onclick=()=>restoreVersion(row.id,side);actions.append(button);}tr.append(actions);table.append(tr);}container.append(table);}
async function restoreVersion(id,side){if(busy)return;try{const history=await api('/api/audit/'+id);const snapshot=history.entry[side];const text=snapshot?'Restore “'+snapshot.name+'” to '+(side==='before'?'the state before ':'')+'version '+history.entry.revision+'?':'Restore this version by removing the record?';if(!confirm(text+' The current state stays in the edit history.'))return;busy=true;await api('/api/rollback/'+id,{method:'POST',body:JSON.stringify({side,revision:history.currentRevision})});location.reload();}catch(e){tell(e.message);}finally{busy=false;}}
$('#audit-refresh').onclick=()=>loadAudit().catch(e=>tell(e.message));
$('#admin-open').onclick=async()=>{try{const state=await api('/api/session');if(state.authenticated)await unlock();else{$('#admin-login').hidden=false;$('#admin-login input').focus();}}catch(e){tell(e.message);}};
$('#admin-login').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;try{await api('/api/login',{method:'POST',body:JSON.stringify({password:event.target.elements.password.value})});event.target.reset();await unlock();}catch(e){tell(e.message);}finally{busy=false;}};
// v2.5.0: resolve the displayed catalog number to a stable record ID before editing.
$('#project-number-form').onsubmit=event=>{event.preventDefault();if(busy||!catalog)return;const number=Number($('#admin-project-number').value);const id=Number.isInteger(number)&&number>0?numberedIds[number-1]:null;const record=catalog.programs.find(p=>p.id===id);if(!record){$('#project-number-status').textContent='No project found with that number. Check the number in the Atlas and try again.';return;}load(record);form.elements.name.focus();};
// v2.7.0: editor-only live search; choosing a result opens its record without saving.
function searchAdminProjects(){
 const query=canonical($('#admin-project-search').value),results=$('#admin-search-results');results.replaceChildren();results.hidden=!query;
 if(!query||!catalog){$('#admin-search-status').textContent='';return;}
 const terms=query.split(' '),matches=catalog.programs.filter(project=>{const text=canonical(Object.values(project).flat().filter(value=>typeof value==='string').join(' '));return terms.every(term=>text.includes(term));});
 $('#admin-search-status').textContent=matches.length?matches.length+' matching projects — choose one to edit.':'No matching projects.';
 for(const project of matches){const button=document.createElement('button');button.type='button';button.textContent='Project '+String(numberedIds.indexOf(project.id)+1).padStart(2,'0')+' · '+project.name;button.addEventListener('click',()=>{if(busy)return;load(project);results.hidden=true;$('#admin-search-status').textContent='Opened '+project.name;form.elements.name.focus();});results.append(button);}
}
for(const event of ['input','search'])$('#admin-project-search').addEventListener(event,searchAdminProjects);
$('#admin-project-search').addEventListener('keydown',event=>{if(event.key==='Escape'){$('#admin-project-search').value='';searchAdminProjects();}if(event.key==='Enter'){event.preventDefault();const buttons=$('#admin-search-results').querySelectorAll('button');if(buttons.length===1&&!$('#admin-search-results').hidden)buttons[0].click();}});
$('#admin-record').onchange=()=>load(catalog.programs.find(p=>p.id===$('#admin-record').value)||null);
$('#admin-new').onclick=()=>{load(null);form.elements.name.focus();};
$('#country-filter').oninput=()=>{const value=canonical($('#country-filter').value);$('#admin-countries').querySelectorAll('label').forEach(label=>label.hidden=!canonical(label.textContent).includes(value));};
$('#admin-logout').onclick=async()=>{try{await api('/api/logout',{method:'POST'});$('#admin-editor').hidden=true;$('#admin-open').hidden=false;form.reset();tell('Editor locked.');}catch(e){tell(e.message);}};
form.onsubmit=async event=>{event.preventDefault();if(busy)return;const record=Object.fromEntries(fields.map(([name])=>[name,form.elements[name].value.trim()]));record.related=form.elements.related.checked;record.countries=[...form.querySelectorAll('[name=countries]:checked')].map(c=>c.value);record.revision=current?.revision??0;if(!record.countries.length){tell('Choose at least one country.');return;}
 const duplicate=catalog.programs.find(p=>p.id!==current?.id&&canonical(p.name)===canonical(record.name));if(duplicate){tell('A project with this name already exists. Choose it from the Project list to edit.');return;}
 const sourceKey=value=>{try{const u=new URL(value);return u.origin+u.pathname.replace(/\/$/,'');}catch{return value;}};
 const possible=catalog.programs.filter(p=>p.id!==current?.id&&p.countries.some(c=>record.countries.includes(c))&&[p.source,p.source2].filter(Boolean).some(url=>[record.source,record.source2].filter(Boolean).some(candidate=>sourceKey(url)===sourceKey(candidate))));
 if(possible.length&&!confirm('Possible duplicate: '+possible.map(p=>p.name).join(', ')+'. These records share an evidence link and country. Save as a distinct project?'))return;
 busy=true;form.querySelector('button[type=submit]').disabled=true;tell('Saving…');try{await api(current?'/api/records/'+current.id:'/api/records',{method:current?'PUT':'POST',body:JSON.stringify(record)});tell('Saved. Refreshing the atlas…');location.reload();}catch(e){tell(e.message+' Your draft is still here.');}finally{busy=false;form.querySelector('button[type=submit]').disabled=false;}};
$('#admin-delete').onclick=async()=>{if(!current||busy||!confirm('Are you sure?'))return;busy=true;try{await api('/api/records/'+current.id,{method:'DELETE',body:JSON.stringify({revision:current.revision})});location.reload();}catch(e){tell(e.message);}finally{busy=false;}};
})();
